			t.Errorf("Security vulnerability: SSRF to %s should be blocked", url)
		}
		if elapsed > 1000*time.Millisecond {
			t.Errorf("Security vulnerability: Request to %s took %v, may have attempted connection", url, elapsed)
		}
	}
}

