			Success: false,
			Message: "Failed to read file content: " + err.Error(),
		})
	}

	// Parse based on format
	var result ImportResult
	result.Format = format

	switch format {
	case "json":
		var jsonData []interface{}
		if err := json.Unmarshal(body, &jsonData); err != nil {
			// Try object if array fails
			var jsonObj map[string]interface{}
			if err2 := json.Unmarshal(body, &jsonObj); err2 != nil {
				return ctx.JSON(http.StatusBadRequest, ResponseBody{
					Success: false,
					Message: "Invalid JSON format",
				})
			}
			result.RecordCount = 1 // Treat as single record
		} else {
