		records, err := reader.ReadAll()
		if err != nil {
			return ctx.JSON(http.StatusBadRequest, ResponseBody{
				Success: false,
				Message: "Invalid CSV format",
			})
		}
		result.RecordCount = len(records)

	case "xml":
		var xmlData struct {
